/**
 * Whether the dashboard should ask the API now: only while its tab is visible and the operator has
 * touched it (a key, the pointer, a scroll) within `IDLE_MS`. Polling and live streams pause otherwise
 * and resume at the next touch, so a tab left open asks nothing: on Cloudflare every read is a request
 * of the day's budget (100,000 for the Worker and as many for the Durable Objects on the Free plan),
 * shared with the bot.
 *
 * On Cloudflare (`ApiApp.target` `durable`) polling is also slower (`every`): each list read calls the
 * index and every conversation's object.
 */

import { useEffect, useRef, useSyncExternalStore } from "react";

/** Without a touch for this long, the dashboard stops asking. */
export const IDLE_MS = 5 * 60_000;
/** Polling is this many times slower on Cloudflare. */
export const CLOUDFLARE_SLOWER = 3;

const TOUCHES = ["pointerdown", "pointermove", "keydown", "wheel", "touchstart", "focus"] as const;

let last = Date.now();
let timer: ReturnType<typeof setTimeout> | undefined;
let target = "server";
const listeners = new Set<() => void>();

const compute = (): boolean => document.visibilityState === "visible" && Date.now() - last < IDLE_MS;
let active = compute();

function update(): void {
  const next = compute();
  if (next === active) return;
  active = next;
  for (const listener of listeners) listener();
}

function touch(): void {
  // The pointer moves often: once a second is enough.
  if (active && Date.now() - last < 1000) return;
  last = Date.now();
  update();
  clearTimeout(timer);
  timer = setTimeout(update, IDLE_MS + 100);
}

for (const name of TOUCHES) window.addEventListener(name, touch, { passive: true, capture: true });
document.addEventListener("visibilitychange", () => (document.visibilityState === "visible" ? touch() : update()));
timer = setTimeout(update, IDLE_MS + 100);

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether the tab is visible and the operator was there within `IDLE_MS`. */
export function useActive(): boolean {
  return useSyncExternalStore(subscribe, () => active);
}

/** Where the App runs (`ApiApp.target`), which the shell says once it read the composition. */
export function setTarget(value: string): void {
  target = value;
}

/** `ms` for this host: slower on Cloudflare. */
export function every(ms: number): number {
  return target === "durable" ? ms * CLOUDFLARE_SLOWER : ms;
}

/**
 * Calls `tick` every `everyMs` while the dashboard is active (`useActive`), and at once when it
 * becomes active again after a pause. `undefined` polls nothing. Returns whether it is active.
 */
export function usePolling(tick: () => void, everyMs: number | undefined): boolean {
  const isActive = useActive();
  const saved = useRef(tick);
  saved.current = tick;
  const wasActive = useRef(isActive);

  useEffect(() => {
    if (everyMs === undefined || !isActive) {
      wasActive.current = isActive;
      return;
    }
    if (!wasActive.current) saved.current();
    wasActive.current = true;
    const interval = setInterval(() => saved.current(), everyMs);
    return () => clearInterval(interval);
  }, [isActive, everyMs]);

  return isActive;
}

/**
 * The admin API's JSON: what every route of admin-api answers, typed. The dashboard (`src/dashboard/`,
 * a project of its own) keeps an identical copy, `src/dashboard/src/lib/admin-api.ts`: no imports, so
 * it compiles there too. Change both together; the kit's tests check they are the same.
 *
 * Every route needs an operator (`admin.auth`): `Authorization: Bearer <PIKIT_ADMIN_TOKEN>` with
 * admin-auth-token, or the session cookie a browser got from `POST /admin/api/session` (then a `POST`
 * also carries `x-pikit-admin: 1`). An error is an `ApiError` with its status.
 *
 * **The dashboard is a channel of its own.** It reads every conversation, and writes only into its own
 * (keys `dashboard:<uuid>`, `POST /admin/api/conversations`) and as follow-ups to another channel's
 * conversation, whose answers it keeps: the request ids of its messages start with `dashboard:`, and a
 * run only they started is never delivered to the conversation's chat.
 *
 * | Route | Answer |
 * |---|---|
 * | `GET /admin/api/app` | `ApiApp`: the composition (`APP_DESCRIPTION`, no secrets) |
 * | `GET /admin/api/agents` | `ApiAgents`: the App's agents, their model and tools |
 * | `POST /admin/api/session` | the credential once → `200 ApiSession` and a session cookie (a browser's) |
 * | `DELETE /admin/api/session` | `204`: the session cookie cleared |
 * | `GET /admin/api/conversations?limit&cursor&archived` | `ApiPage<ApiConversation>`, the most recently active first: those listed, or with `archived=1` those archived |
 * | `POST /admin/api/conversations` | `ApiStartRequest` → `201 ApiStartResponse`: a conversation of the dashboard's own |
 * | `GET /admin/api/conversations/:id` | `ApiConversation` |
 * | `GET /admin/api/conversations/:id/transcript?limit&cursor` | `ApiPage<ApiTranscriptEntry>`, newest first |
 * | `GET /admin/api/conversations/:id/events` | server-sent events, one `ApiEvent` per `data:` line; `snapshot` first |
 * | `POST /admin/api/conversations/:id/messages` | `ApiSendRequest` → `202 ApiSendResponse` |
 * | `POST /admin/api/conversations/:id/abort` | `200 ApiAbortResponse` |
 * | `POST /admin/api/conversations/:id/reset` | `200 ApiResetResponse` |
 * | `POST /admin/api/conversations/:id/archive`, `…/unarchive`, `…/delete` | `200 ApiHideResponse`: the list only (a deleted one is never listed again, nothing of the runtime's is deleted; new activity lists either again) |
 * | `GET /admin/api/commands` | `ApiCommands`: the slash commands the App registered (`agent.command`) |
 * | `POST /admin/api/conversations/:id/commands/:name` | `ApiCommandRequest` → `200 ApiCommandResponse`: the command run in the conversation |
 * | `GET /admin/api/delivery/pending?limit&cursor` | `ApiPage<ApiPendingPiece>`, oldest stored first (with `outbound.queue`) |
 * | `GET /admin/api/delivery/receipts?after&limit` | `ApiReceiptsPage`, in the order they settled (with `outbound.queue`) |
 */

/** The keys of the dashboard's own conversations: `dashboard:<uuid>`. No other channel makes one. */
export const DASHBOARD_KEY_PREFIX = "dashboard:";

/** Whether `key` is one of the dashboard's own conversations. */
export const isDashboardKey = (key: string | undefined): boolean => key?.startsWith(DASHBOARD_KEY_PREFIX) === true;

/** How every message from the dashboard starts, as the agent reads it (`operatorPrompt`). */
export const OPERATOR_NOTE = "[From the operator, in the pikit dashboard";

/** The tool an agent searches the web with (`tool-websearch-brave` provides it under this name). */
export const WEB_SEARCH_TOOL = "websearch";

/**
 * `text` as the agent reads it, sent from the dashboard to the conversation `key`: a first line says it
 * comes from the operator, and, in another channel's conversation, that its user sees neither it nor
 * the answer; with `webSearch`, that the agent is to search the web for it (`WEB_SEARCH_TOOL`).
 */
export function operatorPrompt(key: string, text: string, options: { webSearch?: boolean } = {}): string {
  const asks = [
    ...(isDashboardKey(key) ? [] : ["the user of this conversation does not see this message or your answer to it"]),
    ...(options.webSearch === true ? [`search the web for it with the ${WEB_SEARCH_TOOL} tool before you answer`] : []),
  ];
  const note = asks.length === 0 ? `${OPERATOR_NOTE}.]` : `${OPERATOR_NOTE}: ${asks.join("; ")}.]`;
  return `${note}\n${text}`;
}

/** The longest title a conversation has (`cleanTitle`). */
export const TITLE_MAX = 60;

/** Labels a model may put before a title ("Title: …"), in a few languages: taken off. */
const TITLE_LABEL = /^(?:title|name|subject|topic|t\u00edtulo|titulo|titre|titel|titolo|nombre|nom)(?:\s*:\s*|\s+[-\u2013\u2014]\s+)/i;
/** Quotes and markdown a title is wrapped in. */
const TITLE_WRAP = /^[\s"'`*_#>\u2018\u2019\u201c\u201d\u00ab\u00bb\u300c\u300d-]+|[\s"'`*_\u2018\u2019\u201c\u201d\u00ab\u00bb\u300c\u300d]+$/g;

/**
 * A presentable title from `text` (a model's answer, or what an operator wrote with `/name`), or
 * `undefined` when nothing is left: its first line that has words, without a label ("Title:"),
 * quotes or markdown around it, its spaces collapsed, no `.`, `,`, `;` or `:` at its end, its first
 * letter a capital, at most `TITLE_MAX` characters (cut at a word, with an ellipsis).
 */
export function cleanTitle(text: string): string | undefined {
  const line = text
    .split(/\r?\n/)
    .map((each) => each.replace(TITLE_WRAP, "").replace(TITLE_LABEL, "").replace(TITLE_WRAP, "").replace(/\s+/g, " ").trim())
    .find((each) => /[\p{L}\p{N}]/u.test(each));
  if (line === undefined) return undefined;
  let title = line.replace(/[.,;:\s]+$/u, "");
  if (title.length > TITLE_MAX) {
    const cut = title.slice(0, TITLE_MAX - 1);
    const space = cut.lastIndexOf(" ");
    title = `${(space >= TITLE_MAX / 3 ? cut.slice(0, space) : cut).replace(/[.,;:\s]+$/u, "")}\u2026`;
  }
  return title === "" ? undefined : title.charAt(0).toLocaleUpperCase() + title.slice(1);
}

/** The images an operator may attach to a message: these types, `MAX_IMAGES` of `MAX_IMAGE_BYTES` at most. */
export const IMAGE_TYPES: readonly string[] = ["image/png", "image/jpeg", "image/webp", "image/gif"];
export const MAX_IMAGES = 4;
export const MAX_IMAGE_BYTES = 5 * 1024 * 1024;
/**
 * On Cloudflare (`ApiApp.target` `durable`), the images of one message in all: the message is stored in
 * one Durable Object row, which holds at most 2 MB, and the images grow by a third in base64.
 */
export const MAX_DURABLE_IMAGE_BYTES = 1024 * 1024;

/** The bytes base64 `data` decodes to. */
export const base64Bytes = (data: string): number => Math.floor((data.length * 3) / 4) - (data.endsWith("==") ? 2 : data.endsWith("=") ? 1 : 0);

const BASE64 = /^[A-Za-z0-9+/]*={0,2}$/;

/**
 * What is wrong with a message's `attachments`, or `undefined`: too many, not an image of
 * `IMAGE_TYPES`, or not base64 (`400`); one larger than `MAX_IMAGE_BYTES`, or on `target` `durable`
 * more than `MAX_DURABLE_IMAGE_BYTES` in all (`413`). The dashboard checks with it before sending, and
 * the API again.
 */
export function attachmentsProblem(attachments: readonly ApiAttachment[], target?: string): { status: 400 | 413; message: string } | undefined {
  if (attachments.length > MAX_IMAGES) return { status: 400, message: `at most ${MAX_IMAGES} images a message` };
  let total = 0;
  for (const [i, attachment] of attachments.entries()) {
    if (attachment.kind !== "image" || !IMAGE_TYPES.includes(attachment.mimeType)) return { status: 400, message: `attachment ${i + 1}: an image is ${IMAGE_TYPES.join(", ")}` };
    if (attachment.data.length % 4 !== 0 || !BASE64.test(attachment.data)) return { status: 400, message: `attachment ${i + 1}: its data is not base64` };
    const bytes = base64Bytes(attachment.data);
    if (bytes > MAX_IMAGE_BYTES) return { status: 413, message: `attachment ${i + 1}: an image is at most ${MAX_IMAGE_BYTES / 1024 / 1024} MB` };
    total += bytes;
  }
  if (target === "durable" && total > MAX_DURABLE_IMAGE_BYTES) {
    return { status: 413, message: `on Cloudflare the images of a message are at most ${MAX_DURABLE_IMAGE_BYTES / 1024 / 1024} MB in all (a Durable Object row holds 2 MB)` };
  }
  return undefined;
}

/** What a conversation cost: every model call and tool summed (pi-ai's `Usage`). */
export interface ApiUsage {
  input: number;
  output: number;
  cacheRead: number;
  cacheWrite: number;
  totalTokens: number;
  cost: { input: number; output: number; cacheRead: number; cacheWrite: number; total: number };
}

/** One conversation of the runtime. */
export interface ApiConversation {
  /**
   * What `:id` is in the routes, opaque (encode it in a path): the runtime's id on a server,
   * `<key>~<the object's id>` on Cloudflare, where each conversation's object numbers its own.
   */
  conversationId: string;
  /**
   * Its conversation key (`telegram:12345`) and agent, once a message reached it or a reset pointed
   * its key to it (a reset's new conversation is its key's current one, talked to at once).
   */
  key?: string;
  agent?: string;
  /** Whether a run is going now. */
  busy: boolean;
  /** Epoch ms of its newest message. */
  lastActivity?: number;
  usage: ApiUsage;
  /**
   * Whether its key points to it now. `false` for a conversation a reset left behind: it can be read,
   * not talked to. Absent when it has no key: no message reached it and no reset pointed a key to it.
   */
  current?: boolean;
  /**
   * Its key's title (`cleanTitle`), shared by the conversations a reset left behind: the one a model
   * gave it after its first run, or the operator's (`/name`). Absent until then.
   */
  title?: string;
}

/** One page, and the cursor of the next (absent on the last page). */
export interface ApiPage<T> {
  items: T[];
  next?: string;
}

/** One entry of a conversation's history: its messages in the runtime's JSON (pi-ai's `Message`). */
export interface ApiTranscriptEntry {
  id: string;
  /** `message`, `pi.reset`, …: the runtime's words. */
  kind: string;
  messages: unknown[];
}

/**
 * One live event of a conversation, in the runtime's JSON. The first is a `snapshot` of what the
 * conversation is now; a client that fell behind gets a new `snapshot`, so a view is rebuilt from the
 * last `snapshot` and the events after it, never from a count of events.
 */
export interface ApiEvent {
  type: string;
  [field: string]: unknown;
}

/** One of the App's agents (`agent.definition`), as it is defined. */
export interface ApiAgent {
  name: string;
  /** `provider/modelId`. */
  model: string;
  /**
   * The names of the tools it is defined with (its `tools`; a tool object by its name). Not the tools
   * its extensions bring, nor those a `prepare` gives for a state.
   */
  tools: string[];
}

export interface ApiAgents {
  /** By name. */
  items: ApiAgent[];
}

/** An image attached to a message: the model reads it with the text, and the transcript keeps it. */
export interface ApiImageAttachment {
  kind: "image";
  /** One of `IMAGE_TYPES`. */
  mimeType: string;
  /** Its bytes, base64 (standard, padded), without a `data:` prefix: at most `MAX_IMAGE_BYTES`. */
  data: string;
}

export type ApiAttachment = ApiImageAttachment;

/**
 * A message from an operator to a conversation: a follow-up (with a run going it waits for it), whose
 * answer stays in the dashboard. The agent reads it after `operatorPrompt`'s first line.
 */
export interface ApiSendRequest {
  /** May be empty when it has attachments. */
  text: string;
  /** Images, at most `MAX_IMAGES` (`attachmentsProblem`: `400`, `413`). */
  attachments?: ApiAttachment[];
  /**
   * The agent is told, in the message's first line, to search the web for it. Only for an agent with
   * the tool `WEB_SEARCH_TOOL`: another is `400`.
   */
  webSearch?: boolean;
  /**
   * Its identity: the same one sent again does not run again. `dashboard:` then 1 to 118 of
   * `A-Z a-z 0-9 . _ ~ : -`. Absent, admin-api makes one.
   */
  requestId?: string;
}

export interface ApiSendResponse {
  requestId: string;
  /** `started`: a run started; `queued`: it waits for the run going; `duplicate`: already there. */
  admission: "started" | "queued" | "duplicate";
}

/** A new conversation of the dashboard's own, with its first message. */
export interface ApiStartRequest {
  /** One of the App's agents: the keys of `agent.definition` in `ApiApp.capabilities`. */
  agent: string;
  /** As `ApiSendRequest`'s. */
  text: string;
  attachments?: ApiAttachment[];
  webSearch?: boolean;
  /** As `ApiSendRequest.requestId`. */
  requestId?: string;
}

export interface ApiStartResponse extends ApiSendResponse {
  conversationId: string;
  /** `dashboard:<uuid>`. */
  key: string;
}

/** A slash command the App registered (`agent.command`), as a menu lists it. */
export interface ApiCommand {
  /** Without its slash: `new`, `name`, `compact`. */
  name: string;
  /** One line. */
  description: string;
  /** What its arguments are: `<title>`. Absent: it takes none. */
  argumentHint?: string;
}

export interface ApiCommands {
  /** By name. Empty when the App registered none. */
  items: ApiCommand[];
}

/** A command run in a conversation: what follows its name. */
export interface ApiCommandRequest {
  /** The text after `/name `, at most `MAX_COMMAND_ARGS` characters; absent or empty: none. */
  args?: string;
}

/** The longest arguments a command takes, in characters. */
export const MAX_COMMAND_ARGS = 4_000;

/**
 * What a command answered: a note for the operator (the dashboard shows it in the conversation,
 * quietly; no channel gets it, and it is in the transcript only if the command wrote there), or none.
 */
export interface ApiCommandResponse {
  text?: string;
}

/** A browser's session, opened. */
export interface ApiSession {
  /** The operator's id, as `admin.auth` names it. */
  operator: string;
}

export interface ApiAbortResponse {
  conversationId: string;
}

/** What archive, unarchive and delete did: the conversation, put away or back in the list. */
export interface ApiHideResponse {
  conversationId: string;
}

export interface ApiResetResponse {
  key: string;
  /** The conversation the key pointed to, kept and readable. */
  previousConversationId: string;
  /** The new, empty conversation the key points to now. */
  conversationId: string;
}

/** A piece of an answer not delivered yet (`outbound.queue`'s `pending`). Never its text. */
export interface ApiPendingPiece {
  idempotencyKey: string;
  /** Which of the answer's pieces: 0 is the first. */
  index: number;
  channel: string;
  conversationKey: string;
  /** `queued`: never tried; `sending`: in flight; `retrying`: tried, waiting to go again. */
  state: "queued" | "sending" | "retrying";
  attempts: number;
  /** Epoch ms before which it is not tried again; absent while sending. */
  nextAttemptAt?: number;
  /** Why its last try did not deliver it, short. */
  lastError?: string;
  /** Its next send may repeat one that reached the platform. */
  possibleDuplicate: boolean;
  storedAt: number;
}

/** A piece that settled (`outbound.queue`'s `receipts`), with the cursor to read after it. */
export interface ApiReceipt {
  cursor: string;
  idempotencyKey: string;
  index: number;
  channel: string;
  conversationKey: string;
  attempts: number;
  outcome: { kind: "delivered"; platformMessageId: string; possibleDuplicate: boolean } | { kind: "abandoned"; reason: string };
  /** Epoch ms when it settled. */
  at: number;
}

/** Receipts after a cursor: `next` is the last one's, to read on from; `gap`: some were pruned before this read. */
export interface ApiReceiptsPage {
  items: ApiReceipt[];
  gap: boolean;
  next?: string;
}

/**
 * The composition (`AppDescription`, K13): JSON, no secrets. A config value that looks like one (under a
 * key such as `token`, `secret`, `password`, `apiKey`, or shaped like a credential) is `[redacted]`.
 */
export interface ApiApp {
  version: number;
  target: string;
  components: { name: string; version?: string; provides: string[]; requires: string[]; optional: string[] }[];
  capabilities: Record<string, { providers: string[]; selected?: string; keys?: Record<string, string> }>;
  pipelines: Record<string, unknown[]>;
  config: Record<string, unknown>;
}

export interface ApiError {
  /**
   * `unauthorized`, `not_found`, `not_installed`, `invalid_request`, `invalid_cursor`, `no_agent`,
   * `not_current`, `unknown_agent`, `too_large` (413: an image, or a body, larger than the API takes),
   * `unknown_command` (404: no command of that name), `command_failed` (422: the command could not do
   * it, its message says why);
   * `unavailable` (503) when, on Cloudflare, a conversation's object did not answer.
   */
  error: string;
  message?: string;
}

/**
 * The admin API (admin-api, `/admin/api/*`), from the browser. Its JSON is typed in `admin-api.ts`, an
 * identical copy of admin-api's own `api.ts` (`src/pikit/admin-api/api.ts`): change both together.
 *
 * **Signing in** (`signIn`) posts the operator's token once, to `POST /admin/api/session`, which
 * answers with a session cookie (HttpOnly, SameSite=Strict, sent to `/admin/api/` only, expiring):
 * the token is kept nowhere, and no script can read the session. `signOut` clears it. Every call
 * carries the header `x-pikit-admin: 1`, which a page of another site cannot send, so the cookie
 * alone changes nothing. An `admin.auth` without browser sessions (`404 not_installed`): the token is
 * kept in this page's memory only, and asked again after a reload.
 *
 * A browser's `EventSource` cannot send the header, so live events are read with `fetch`.
 */

import { useCallback, useEffect, useRef, useState } from "react";
import { usePolling } from "./activity.ts";
import type { ApiError, ApiEvent, ApiSession } from "./admin-api.ts";

export type * from "./admin-api.ts";

const API = "/admin/api";
/** `ADMIN_CLIENT_HEADER` (@pikit/contracts): what makes a call the dashboard's own. */
const CLIENT_HEADER = "x-pikit-admin";

/** The token, when the API has no browser sessions: this page's memory only. */
let memoryToken: string | undefined;

/** An answer that is not a success: its status and the API's error. */
export class ApiFailure extends Error {
  readonly status: number;
  readonly body: ApiError;
  constructor(status: number, body: ApiError) {
    super(body.message ?? body.error);
    this.status = status;
    this.body = body;
  }
}

/** Listeners told when the API refuses the token (401): the app asks for it again. */
const unauthorized = new Set<() => void>();
export function onUnauthorized(listener: () => void): () => void {
  unauthorized.add(listener);
  return () => unauthorized.delete(listener);
}

function headers(extra?: HeadersInit): Headers {
  const all = new Headers(extra);
  all.set(CLIENT_HEADER, "1");
  if (memoryToken !== undefined) all.set("authorization", `Bearer ${memoryToken}`);
  return all;
}

/**
 * Signs in with the operator's `token` (PIKIT_ADMIN_TOKEN with admin-auth-token): a session cookie,
 * or, without browser sessions, the token in memory. Answers the operator's id when the API names it.
 * Throws an `ApiFailure` (`401`: not the token).
 */
export async function signIn(token: string): Promise<string | undefined> {
  const response = await fetch(`${API}/session`, { method: "POST", headers: { [CLIENT_HEADER]: "1", authorization: `Bearer ${token}` } });
  if (response.ok) {
    memoryToken = undefined;
    const session = (await response.json().catch(() => undefined)) as ApiSession | undefined;
    return typeof session?.operator === "string" ? session.operator : undefined;
  }
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  if (response.status !== 404 || body.error !== "not_installed") throw new ApiFailure(response.status, body);
  // No sessions: the token goes with every call, from memory, if the API takes it.
  memoryToken = token;
  try {
    await api("/app");
  } catch (error) {
    memoryToken = undefined;
    throw error;
  }
  return undefined;
}

/** Signs out: the session cookie cleared (and the token forgotten). */
export async function signOut(): Promise<void> {
  memoryToken = undefined;
  await fetch(`${API}/session`, { method: "DELETE", headers: { [CLIENT_HEADER]: "1" } }).catch(() => undefined);
}

async function failure(response: Response): Promise<ApiFailure> {
  if (response.status === 401) for (const listener of unauthorized) listener();
  const body = (await response.json().catch(() => ({ error: `http_${response.status}` }))) as ApiError;
  return new ApiFailure(response.status, body);
}

/** `GET` (or `init`'s method) of `path` under /admin/api, as JSON. */
export async function api<T>(path: string, init: RequestInit = {}): Promise<T> {
  const response = await fetch(`${API}${path}`, { ...init, headers: headers(init.headers) });
  if (!response.ok) throw await failure(response);
  return (await response.json()) as T;
}

/** `POST` of `body` (JSON) to `path` under /admin/api. */
export function post<T>(path: string, body?: unknown): Promise<T> {
  return api<T>(path, {
    method: "POST",
    headers: { "content-type": "application/json" },
    ...(body !== undefined && { body: JSON.stringify(body) }),
  });
}

/**
 * Follows `path`'s server-sent events until `signal` aborts or the stream ends: each `data:` line is
 * one event. Resolves when the stream ends; rejects when it cannot start.
 */
export async function follow(path: string, onEvent: (event: ApiEvent) => void, signal: AbortSignal): Promise<void> {
  const response = await fetch(`${API}${path}`, { headers: headers({ accept: "text/event-stream" }), signal });
  if (!response.ok || response.body === null) throw await failure(response);
  const reader = response.body.pipeThrough(new TextDecoderStream()).getReader();
  let buffer = "";
  try {
    for (;;) {
      const { value, done } = await reader.read();
      if (done) return;
      buffer += value;
      let end = buffer.indexOf("\n\n");
      while (end !== -1) {
        const frame = buffer.slice(0, end);
        buffer = buffer.slice(end + 2);
        const data = frame
          .split("\n")
          .filter((line) => line.startsWith("data: "))
          .map((line) => line.slice(6))
          .join("\n");
        if (data !== "" && !frame.startsWith("event: error")) onEvent(JSON.parse(data) as ApiEvent);
        end = buffer.indexOf("\n\n");
      }
    }
  } catch (error) {
    if (signal.aborted) return;
    throw error;
  } finally {
    reader.releaseLock();
  }
}

export interface Loaded<T> {
  data: T | undefined;
  error: Error | undefined;
  loading: boolean;
  reload(): void;
}

/** `GET path`, again on `reload()`, and every `everyMs` when given while the dashboard is active. `null` loads nothing. */
export function useApi<T>(path: string | null, everyMs?: number): Loaded<T> {
  const [data, setData] = useState<T>();
  const [error, setError] = useState<Error>();
  const [loading, setLoading] = useState(path !== null);
  const [round, setRound] = useState(0);
  const current = useRef(path);
  current.current = path;

  useEffect(() => {
    if (path === null) return;
    let live = true;
    setLoading(true);
    api<T>(path)
      .then((value) => live && current.current === path && (setData(value), setError(undefined)))
      .catch((thrown: unknown) => live && setError(thrown instanceof Error ? thrown : new Error(String(thrown))))
      .finally(() => live && setLoading(false));
    return () => {
      live = false;
    };
  }, [path, round]);

  const reload = useCallback(() => setRound((n) => n + 1), []);
  // Only while the operator is here (`activity.ts`).
  usePolling(reload, path === null ? undefined : everyMs);
  return { data, error, loading, reload };
}

/**
 * The conversations the sidebar and the tabs show: every one, the most recently active first (the
 * API's index: the first page read again every 10 s while the dashboard is active, 30 s on
 * Cloudflare, older pages on demand), the tabs the operator opened, and what the commands answered.
 *
 * A title names a conversation key, so the conversations a reset left behind share it with the key's
 * current one. It is the API's (`ApiConversation.title`: a model's, made after the key's first run, or
 * the operator's `/name`); until there is one, the first message written in the key when this page
 * has it at hand (sent from the home, or read in the open conversation's transcript: never looked
 * for), else for another channel's key the id in it (`telegram:12345` is `12345`), and "New chat" for
 * one of the dashboard's own. A conversation with no key (no message reached it and no reset pointed a
 * key to it) has nothing to show or do: the list leaves it out. Tabs are kept in
 * `localStorage["pikit-tabs"]`.
 *
 * The operator puts a conversation away from its row (`hide`): archived (listed apart, `archived`,
 * read when opened) or deleted (never listed again). The list only: the runtime keeps it, and new
 * activity (a person writes again) lists it again by itself.
 */

import { createContext, type ReactNode, useCallback, useContext, useEffect, useMemo, useState } from "react";
import { every, usePolling } from "./activity.ts";
import { cleanTitle, isDashboardKey } from "./admin-api.ts";
import { api, type ApiApp, type ApiConversation, type ApiPage, post } from "./api.ts";

const PAGE = 50;
const TABS = "pikit-tabs";
/** Tabs kept. */
const KEPT_TABS = 12;
/** The title of a dashboard conversation with no title and no first message at hand. */
export const NEW_CHAT = "New chat";

/** What a command answered in a conversation: a quiet note there, in this page only (no channel gets it). */
export interface CommandNote {
  id: number;
  /** The command, without its slash. */
  command: string;
  text: string;
  at: number;
}

let nextNote = 0;

export interface Tab {
  id: string;
  /** Its conversation's key: its title follows the key's. */
  key?: string;
  title: string;
}

function load<T>(key: string, fallback: T): T {
  try {
    const raw = localStorage.getItem(key);
    return raw === null ? fallback : (JSON.parse(raw) as T);
  } catch {
    return fallback;
  }
}

function save(key: string, value: unknown): void {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // Not kept: this page still has it.
  }
}

/** The App's agents: the keys of `agent.definition`. */
export const agentsOf = (app: ApiApp | undefined): string[] => Object.keys(app?.capabilities["agent.definition"]?.keys ?? {}).sort();

/** The agent the App answers with when none is named (router-basic's `defaultAgent`), if it is one of `agents`. */
export function defaultAgentOf(app: ApiApp | undefined): string | undefined {
  const agents = agentsOf(app);
  const named = (app?.config["router-basic"] as { defaultAgent?: unknown } | undefined)?.defaultAgent;
  return typeof named === "string" && agents.includes(named) ? named : agents[0];
}

export interface Chats {
  /** Undefined until the first page is read. */
  items: ApiConversation[] | undefined;
  error: Error | undefined;
  hasOlder: boolean;
  loadOlder(): Promise<void>;
  reload(): void;
  /** Its key's title: the API's, else the first message at hand, the id in its key, or `NEW_CHAT`. */
  titleOf(conversation: ApiConversation): string;
  /** A tab's title: its key's, as it is now. */
  tabTitle(tab: Tab): string;
  /** The first message written in `key`, as this page knows it: the title until the API has one. */
  setFirstMessage(key: string, text: string): void;
  /** The notes the commands run in conversation `id` answered, oldest first. */
  notesOf(id: string): CommandNote[];
  /** A command's answer in conversation `id`. */
  addNote(id: string, command: string, text: string): void;
  tabs: Tab[];
  /** Opens (or refreshes) the tab of `conversation`. */
  openTab(conversation: ApiConversation): void;
  /** Closes a tab; answers the tab to show instead when it was `active`. */
  closeTab(id: string): Tab | undefined;
  /** The conversation `from` was reset into `to`: its tab follows (the title is the key's). */
  replaced(from: string, to: string): void;
  /** The archived ones, the most recently active first; undefined until `loadArchived` read them. */
  archived: ApiConversation[] | undefined;
  loadArchived(): void;
  /** Archives, restores (`unarchive`) or deletes a conversation: from the list only. Its tab closes when it leaves the list. */
  hide(id: string, action: "archive" | "unarchive" | "delete"): Promise<void>;
}

const ChatsContext = createContext<Chats | undefined>(undefined);

export function useChats(): Chats {
  const chats = useContext(ChatsContext);
  if (chats === undefined) throw new Error("useChats: outside ChatsProvider");
  return chats;
}

export function ChatsProvider({ children }: { children: ReactNode }) {
  const [first, setFirst] = useState<ApiPage<ApiConversation>>();
  const [older, setOlder] = useState<ApiConversation[]>([]);
  const [next, setNext] = useState<string | null>();
  const [error, setError] = useState<Error>();
  const [firsts, setFirsts] = useState<Record<string, string>>({});
  const [notes, setNotes] = useState<Record<string, CommandNote[]>>({});
  const [tabs, setTabs] = useState<Tab[]>(() => load<Tab[]>(TABS, []).filter((tab) => typeof tab?.id === "string"));
  const [archived, setArchived] = useState<ApiConversation[]>();
  /** Put away by this page, with their activity then: left out of the pages read until newer activity lists one again. */
  const [gone, setGone] = useState<ReadonlyMap<string, number>>(new Map());

  const reload = useCallback(() => {
    api<ApiPage<ApiConversation>>(`/conversations?limit=${PAGE}`)
      .then((page) => (setFirst(page), setError(undefined)))
      .catch((thrown: unknown) => setError(thrown instanceof Error ? thrown : new Error(String(thrown))));
  }, []);
  useEffect(reload, [reload]);
  usePolling(reload, every(10_000));

  const cursor = next === undefined ? first?.next : (next ?? undefined);
  const loadOlder = useCallback(async () => {
    if (cursor === undefined) return;
    try {
      const page = await api<ApiPage<ApiConversation>>(`/conversations?limit=${PAGE}&cursor=${encodeURIComponent(cursor)}`);
      setOlder((items) => [...items, ...page.items]);
      setNext(page.next ?? null);
    } catch (thrown) {
      setError(thrown instanceof Error ? thrown : new Error(String(thrown)));
    }
  }, [cursor]);

  useEffect(() => save(TABS, tabs.slice(-KEPT_TABS)), [tabs]);

  // The API's titles, by key: any conversation of a key carries it.
  const titled = useMemo(() => {
    const byKey = new Map<string, string>();
    for (const each of [...(first?.items ?? []), ...older]) if (each.key !== undefined && each.title !== undefined) byKey.set(each.key, each.title);
    return byKey;
  }, [first, older]);

  const titleOfKey = useCallback(
    (key: string | undefined, title?: string): string => {
      if (key === undefined) return NEW_CHAT;
      const known = title ?? titled.get(key) ?? firsts[key];
      if (known !== undefined) return known;
      return isDashboardKey(key) ? NEW_CHAT : key.slice(key.indexOf(":") + 1) || key;
    },
    [titled, firsts],
  );
  const titleOf = useCallback((conversation: ApiConversation): string => titleOfKey(conversation.key, conversation.title), [titleOfKey]);
  const tabTitle = useCallback((tab: Tab): string => (tab.key === undefined ? tab.title : titleOfKey(tab.key)), [titleOfKey]);

  const setFirstMessage = useCallback((key: string, text: string) => {
    const title = cleanTitle(text);
    if (title === undefined) return;
    setFirsts((all) => (all[key] !== undefined ? all : { ...all, [key]: title }));
  }, []);

  const notesOf = useCallback((id: string): CommandNote[] => notes[id] ?? [], [notes]);
  const addNote = useCallback((id: string, command: string, text: string) => {
    setNotes((all) => ({ ...all, [id]: [...(all[id] ?? []), { id: nextNote++, command, text, at: Date.now() }] }));
  }, []);

  const openTab = useCallback(
    (conversation: ApiConversation) => {
      const tab: Tab = { id: conversation.conversationId, ...(conversation.key !== undefined && { key: conversation.key }), title: titleOf(conversation) };
      setTabs((all) => {
        const at = all.findIndex((each) => each.id === tab.id);
        if (at === -1) return [...all, tab].slice(-KEPT_TABS);
        const known = all[at];
        return known?.title === tab.title && known.key === tab.key ? all : all.map((each, i) => (i === at ? tab : each));
      });
    },
    [titleOf],
  );

  const closeTab = useCallback(
    (id: string) => {
      const at = tabs.findIndex((tab) => tab.id === id);
      setTabs((all) => all.filter((tab) => tab.id !== id));
      return at === -1 ? undefined : (tabs[at + 1] ?? tabs[at - 1]);
    },
    [tabs],
  );

  const replaced = useCallback((from: string, to: string) => {
    setTabs((all) => all.map((tab) => (tab.id === from ? { ...tab, id: to } : tab)));
  }, []);

  // A conversation active again since the older pages were read is on the first page: shown once.
  // One with no key has nothing to show or do: left out; so is one this page just put away.
  const items = useMemo(() => {
    if (first === undefined) return undefined;
    const seen = new Set<string>();
    return [...first.items, ...older].filter((each) => each.key !== undefined && !gone.has(each.conversationId) && !seen.has(each.conversationId) && seen.add(each.conversationId));
  }, [first, older, gone]);

  const loadArchived = useCallback(() => {
    api<ApiPage<ApiConversation>>(`/conversations?archived=1&limit=${PAGE}`)
      .then((page) => setArchived(page.items.filter((each) => each.key !== undefined)))
      .catch((thrown: unknown) => setError(thrown instanceof Error ? thrown : new Error(String(thrown))));
  }, []);

  const hide = useCallback(
    async (id: string, action: "archive" | "unarchive" | "delete") => {
      await post(`/conversations/${encodeURIComponent(id)}/${action}`);
      if (action === "unarchive") setGone((all) => new Map([...all].filter(([each]) => each !== id)));
      else {
        const at = [...(first?.items ?? []), ...older].find((each) => each.conversationId === id)?.lastActivity ?? 0;
        setGone((all) => new Map([...all, [id, at]]));
        setTabs((all) => all.filter((tab) => tab.id !== id));
      }
      if (archived !== undefined || action !== "delete") loadArchived();
      reload();
    },
    [archived, first, older, loadArchived, reload],
  );

  // Active again since it was put away (a person wrote): the API lists it again, and so does this page.
  useEffect(() => {
    if (first === undefined || gone.size === 0) return;
    const back = first.items.filter((each) => (gone.get(each.conversationId) ?? Infinity) < (each.lastActivity ?? 0)).map((each) => each.conversationId);
    if (back.length > 0) setGone((all) => new Map([...all].filter(([id]) => !back.includes(id))));
  }, [first, gone]);

  const value: Chats = { items, error, hasOlder: cursor !== undefined, loadOlder, reload, titleOf, tabTitle, setFirstMessage, notesOf, addNote, tabs, openTab, closeTab, replaced, archived, loadArchived, hide };
  return <ChatsContext.Provider value={value}>{children}</ChatsContext.Provider>;
}

/** Small formatting helpers shared by views. */

import type { ApiUsage } from "./api.ts";

/** A cost in dollars: `$0.0042`, `$1.23`. */
export function formatCost(usage: ApiUsage | undefined): string {
  const total = usage?.cost.total ?? 0;
  if (total === 0) return "$0";
  return `$${total < 0.01 ? total.toFixed(4) : total.toFixed(2)}`;
}

/** Tokens, short: `950`, `12.3k`, `1.2M`. */
export function formatTokens(count: number): string {
  if (count < 1000) return String(count);
  if (count < 1_000_000) return `${(count / 1000).toFixed(1)}k`;
  return `${(count / 1_000_000).toFixed(1)}M`;
}

const relative = new Intl.RelativeTimeFormat(undefined, { numeric: "auto" });

/** `3 minutes ago`, from epoch milliseconds. */
export function formatAgo(at: number | undefined, now = Date.now()): string {
  if (at === undefined) return "—";
  const seconds = Math.round((at - now) / 1000);
  const steps: [Intl.RelativeTimeFormatUnit, number][] = [
    ["second", 60],
    ["minute", 60],
    ["hour", 24],
    ["day", 30],
    ["month", 12],
  ];
  let value = seconds;
  for (const [unit, size] of steps) {
    if (Math.abs(value) < size) return relative.format(value, unit);
    value = Math.round(value / size);
  }
  return relative.format(value, "year");
}

/** How the dashboard shows names: no imports, so the kit's tests read it as it is. */

/**
 * An agent's name as the dashboard shows it (the stored name stays as it is): its words, split at
 * `-` and `_`, the first one capitalized. `assistant` is "Assistant", `support-bot` "Support bot".
 */
export function assistantName(name: string): string {
  const words = name.split(/[-_]+/).filter((word) => word !== "").join(" ");
  return words === "" ? name : words.charAt(0).toLocaleUpperCase() + words.slice(1);
}

/**
 * A small router over the History API, under /admin (admin-api answers every path but `/admin/assets/`
 * and its files with index.html, so a reload of any page works). Paths here are relative to /admin:
 * `/conversations/abc` is `/admin/conversations/abc`.
 *
 * A parameter is one path segment, encoded in a link (`encodeURIComponent`: an id such as
 * `email:ana@empresa.com~1` or one with `/`) and decoded by `match`.
 */

import { type AnchorHTMLAttributes, useSyncExternalStore } from "react";

export const BASE = "/admin";

function subscribe(onChange: () => void): () => void {
  window.addEventListener("popstate", onChange);
  return () => window.removeEventListener("popstate", onChange);
}

const path = (): string => {
  const { pathname } = window.location;
  const relative = pathname.startsWith(BASE) ? pathname.slice(BASE.length) : pathname;
  return relative === "" ? "/" : relative;
};

/** The current path, relative to /admin. */
export function usePath(): string {
  return useSyncExternalStore(subscribe, path);
}

export function navigate(to: string, options: { replace?: boolean } = {}): void {
  const url = `${BASE}${to}`;
  if (options.replace === true) window.history.replaceState(null, "", url);
  else window.history.pushState(null, "", url);
  window.dispatchEvent(new PopStateEvent("popstate"));
}

/**
 * The parameters of `pattern` (`/conversations/:id`) in `pathname`, or `undefined` when it does not
 * match.
 */
export function match(pattern: string, pathname: string): Record<string, string> | undefined {
  const want = pattern.split("/").filter(Boolean);
  const have = pathname.split("/").filter(Boolean);
  if (want.length !== have.length) return undefined;
  const params: Record<string, string> = {};
  for (const [i, segment] of want.entries()) {
    const value = have[i] ?? "";
    if (segment.startsWith(":")) {
      try {
        params[segment.slice(1)] = decodeURIComponent(value);
      } catch {
        return undefined;
      }
    } else if (segment !== value) return undefined;
  }
  return params;
}

/** The path of a page with `id` as one segment: `pagePath("/conversations", id)`. */
export function pagePath(base: string, id: string): string {
  return `${base}/${encodeURIComponent(id)}`;
}

/** A link inside the dashboard: `to` is relative to /admin. */
export function Link({ to, onClick, ...rest }: AnchorHTMLAttributes<HTMLAnchorElement> & { to: string }) {
  return (
    <a
      {...rest}
      href={`${BASE}${to}`}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey) return;
        event.preventDefault();
        navigate(to);
      }}
    />
  );
}

/**
 * What the shell (`app.tsx`) gives the pages: the App's composition, its agents, its slash commands, the views it shows,
 * the operator, a new chat (`newChat`), and two places a page can fill: the tab bar's right end
 * (`TabActions`: a conversation's Context button and its menu) and the side panel next to the main pane
 * (`SidePanel`: a conversation's Context).
 */

import { createContext, type ReactNode, useContext, useEffect } from "react";
import { createPortal } from "react-dom";
import type { ApiAgent, ApiApp, ApiCommand } from "./api.ts";
import type { View } from "./views.ts";

export interface ShellState {
  app: ApiApp;
  /** The App's agents (`GET /admin/api/agents`), by name; undefined until read. */
  agents?: ApiAgent[];
  /** The App's slash commands (`GET /admin/api/commands`), by name; undefined until read. */
  commands?: ApiCommand[];
  /** Opens a new chat (the home, its draft empty), with `agent` chosen when given. */
  newChat(agent?: string): void;
  /** The views the App's composition allows, in sidebar order. */
  views: View[];
  /** The signed-in operator's id, when this browser signed in (`ApiSession.operator`). */
  operator?: string;
  /** Where the tab bar's right end and the side panel are, once mounted. */
  slots: { actions: HTMLElement | null; side: HTMLElement | null };
}

export const ShellContext = createContext<ShellState | undefined>(undefined);

export function useShell(): ShellState {
  const shell = useContext(ShellContext);
  if (shell === undefined) throw new Error("useShell: outside the dashboard's shell");
  return shell;
}

/** Shown at the tab bar's right end while the page is. */
export function TabActions({ children }: { children: ReactNode }) {
  const target = useContext(ShellContext)?.slots.actions;
  return target === null || target === undefined ? null : createPortal(children, target);
}

/** A panel of its own next to the main pane (wide screens), while the page is. */
export function SidePanel({ children }: { children: ReactNode }) {
  const target = useContext(ShellContext)?.slots.side;
  return target === null || target === undefined ? null : createPortal(children, target);
}

/** The App's name: `ApiApp` has none yet, so "Pikit" unless one is there. */
export function appName(app: ApiApp): string {
  const name = (app as { name?: unknown }).name;
  return typeof name === "string" && name.trim() !== "" ? name : "Pikit";
}

/**
 * The browser tab's title while a page shows: `<what> · <App>`, or the App's name alone. Every page of
 * the shell sets it (the shell does, from the page it renders), so it never keeps a page's that left.
 */
export function usePageTitle(what: string | undefined, app = "Pikit"): void {
  useEffect(() => {
    document.title = what === undefined || what.trim() === "" ? app : `${what} · ${app}`;
  }, [what, app]);
}

/**
 * Interaction sounds (Beautiful UI's InteractionSounds, MIT: see NOTICE): one quiet cue per click on
 * anything interactive, synthesized with @web-kits/audio. On by default; the operator turns them off
 * in the workspace menu, remembered in this browser (`localStorage["pikit-sounds"]`). Nothing makes
 * an AudioContext before the first click.
 *
 * An element picks its cue with `data-sound="press|tick|release|page|pulse"`; inside
 * `[data-sound-silent]` nothing sounds.
 */

import { defineSound, ensureReady, type PlayOptions, setMasterVolume, type VoiceHandle } from "@web-kits/audio";
import { useSyncExternalStore } from "react";

const KEY = "pikit-sounds";

const INTERACTIVE_SELECTOR = [
  "button",
  "a[href]",
  "input:not([type='hidden'])",
  "select",
  "textarea",
  "summary",
  "[role='button']",
  "[role='checkbox']",
  "[role='menuitem']",
  "[role='menuitemcheckbox']",
  "[role='menuitemradio']",
  "[role='option']",
  "[role='radio']",
  "[role='switch']",
  "[role='tab']",
].join(",");

const DISMISS_WORDS = /close|dismiss|remove|delete|collapse|cancel|clear|stop|abort|reset/i;
const PRIMARY_WORDS = /send|save|submit|start|sign in|create|add/i;

type Cue = "press" | "tick" | "release" | "page" | "pulse";
type Play = (options?: PlayOptions) => VoiceHandle;

/** Five short cues, built on the first click (a browser allows audio only after a gesture). */
function buildCues(): Record<Cue, Play> {
  return {
    // most buttons: a crisp transient blended with a bright pluck
    press: defineSound({
      layers: [
        { source: { type: "noise", color: "white" }, filter: { type: "highpass", frequency: 2400 }, envelope: { attack: 0.0003, decay: 0.009, sustain: 0 }, gain: 0.13 },
        { source: { type: "sine", frequency: 680 }, envelope: { attack: 0.0006, decay: 0.022, sustain: 0, release: 0.008 }, gain: 0.24 },
      ],
    }),
    // toggles, tabs, inputs: a light tick
    tick: defineSound({
      source: { type: "square", frequency: 2100 },
      filter: { type: "bandpass", frequency: 2600, resonance: 1.6 },
      envelope: { attack: 0.0004, decay: 0.028, sustain: 0 },
      gain: 0.24,
    }),
    // close, delete, cancel: a light clack
    release: defineSound({
      source: { type: "noise", color: "white" },
      filter: { type: "lowpass", frequency: 1600, resonance: 0.9 },
      envelope: { attack: 0.001, decay: 0.055, sustain: 0 },
      gain: 0.32,
    }),
    // links, navigation: a soft upward blip
    page: defineSound({
      source: { type: "sine", frequency: { start: 430, end: 640 } },
      envelope: { attack: 0.002, decay: 0.11, sustain: 0, release: 0.03 },
      gain: 0.4,
    }),
    // primary actions: a rounder pulse
    pulse: defineSound({
      source: { type: "sine", frequency: 330 },
      filter: { type: "lowpass", frequency: 2200 },
      envelope: { attack: 0.002, decay: 0.13, sustain: 0, release: 0.04 },
      gain: 0.5,
    }),
  };
}

function cueFor(element: Element): Cue {
  const override = element.getAttribute("data-sound");
  if (override === "press" || override === "tick" || override === "release" || override === "page" || override === "pulse") return override;
  const label = `${element.getAttribute("aria-label") ?? ""} ${element.textContent ?? ""}`.trim();
  if (DISMISS_WORDS.test(label)) return "release";
  if (element.matches("input[type='checkbox'], input[type='radio'], select, [role='checkbox'], [role='radio'], [role='switch'], [role='tab'], [aria-pressed]")) return "tick";
  if (element.matches("a[href]")) return "page";
  if (PRIMARY_WORDS.test(label)) return "pulse";
  if (element.matches("input, textarea")) return "tick";
  return "press";
}

function storedOn(): boolean {
  try {
    return localStorage.getItem(KEY) !== "off";
  } catch {
    return true;
  }
}

let on = storedOn();
let cues: Record<Cue, Play> | undefined;
const listeners = new Set<() => void>();

function onClick(event: MouseEvent): void {
  if (!on || !(event.target instanceof Element)) return;
  const control = event.target.closest(INTERACTIVE_SELECTOR);
  if (control === null || control.closest("[data-sound-silent]") !== null) return;
  if (control.matches(":disabled, [aria-disabled='true']")) return;
  if (cues === undefined) {
    void ensureReady();
    setMasterVolume(0.32);
    cues = buildCues();
  }
  cues[cueFor(control)]();
}

document.addEventListener("click", onClick, true);

export function setSounds(next: boolean): void {
  on = next;
  try {
    localStorage.setItem(KEY, next ? "on" : "off");
  } catch {
    // Not remembered: this page still follows it.
  }
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** Whether interaction sounds play. */
export function useSounds(): boolean {
  return useSyncExternalStore(subscribe, () => on);
}

/**
 * The theme: light, dark, or the system's (the default), remembered in this browser
 * (`localStorage["pikit-theme"]`). `public/theme.js` applies it before the first paint (no inline
 * script: the Content-Security-Policy); this module keeps `<html class="dark">` in step afterwards,
 * the system's changes included.
 */

import { useSyncExternalStore } from "react";

export type Theme = "light" | "dark" | "system";

const KEY = "pikit-theme";
const media = window.matchMedia("(prefers-color-scheme: dark)");
const listeners = new Set<() => void>();

function stored(): Theme {
  try {
    const value = localStorage.getItem(KEY);
    return value === "light" || value === "dark" ? value : "system";
  } catch {
    return "system";
  }
}

let theme = stored();

function apply(): void {
  const dark = theme === "dark" || (theme === "system" && media.matches);
  const root = document.documentElement;
  if (root.classList.contains("dark") === dark) return;
  // Every token flips at once: no transition while it does.
  root.classList.add("theme-switching");
  root.classList.toggle("dark", dark);
  requestAnimationFrame(() => requestAnimationFrame(() => root.classList.remove("theme-switching")));
}

media.addEventListener("change", apply);
apply();

export function setTheme(next: Theme): void {
  theme = next;
  try {
    if (next === "system") localStorage.removeItem(KEY);
    else localStorage.setItem(KEY, next);
  } catch {
    // Not remembered: this page still switches.
  }
  apply();
  for (const listener of listeners) listener();
}

function subscribe(listener: () => void): () => void {
  listeners.add(listener);
  return () => listeners.delete(listener);
}

/** The operator's choice (not what it resolves to). */
export function useTheme(): Theme {
  return useSyncExternalStore(subscribe, () => theme);
}

/**
 * Views: each folder of `src/views/` is one, found when the dashboard is built (nothing is loaded
 * at run time). Its `index.tsx` default-exports `defineView({ … })`:
 *
 *   export default defineView({
 *     id: "memory",                       // the folder's name; its pages live under /memory
 *     title: "Memory",
 *     icon: Brain,
 *     requires: ["memory"],               // shown only when these capabilities are installed
 *     pages: [{ path: "/memory", component: MemoryPage }],
 *   });
 *
 * A view whose `requires` are not all in the App's composition does not appear (SPEC §5). A component
 * that brings a view installs its folder here (`pikit add`, or `shadcn add @pikit/<view>`).
 */

import type { ComponentType } from "react";
import type { ApiApp } from "./api.ts";

export interface ViewPage {
  /** Relative to /admin, starting with the view's `/<id>`; `:name` is a parameter. */
  path: string;
  component: ComponentType<{ params: Record<string, string> }>;
  /** The page fills the main pane and scrolls itself (a chat); otherwise it is shown in a padded, scrolling column. */
  fill?: boolean;
}

export interface View {
  /** The folder's name. */
  id: string;
  title: string;
  icon?: ComponentType<{ className?: string }>;
  /** Capabilities that must be provided in the App for the view to show. */
  requires?: string[];
  /** Its place in the sidebar, lowest first (default 100). `conversations` is the chat, not a sidebar item. */
  order?: number;
  /** Its pages; the first one is the sidebar's link. */
  pages: ViewPage[];
}

export function defineView(view: View): View {
  for (const page of view.pages) {
    if (page.path !== `/${view.id}` && !page.path.startsWith(`/${view.id}/`)) {
      throw new Error(`view "${view.id}": page ${page.path} is not under /${view.id}`);
    }
  }
  return view;
}

const found = import.meta.glob<{ default: View }>("../views/*/index.tsx", { eager: true });

/** Every view of `src/views/`, in sidebar order. */
export const views: View[] = Object.entries(found)
  .map(([file, module]) => {
    const view = module.default;
    const folder = file.split("/").at(-2);
    if (view?.id !== folder) throw new Error(`src/views/${folder}/index.tsx must default-export defineView({ id: "${folder}", … })`);
    return view;
  })
  .sort((a, b) => (a.order ?? 100) - (b.order ?? 100) || a.title.localeCompare(b.title));

/** The views whose capabilities `app` provides. */
export function visibleViews(app: ApiApp): View[] {
  const provided = (name: string) => (app.capabilities[name]?.providers.length ?? 0) > 0;
  return views.filter((view) => (view.requires ?? []).every(provided));
}
